-- Superadmin console (Master DB): audit trail and per-Superadmin appearance. Additive and idempotent; normal backend startup runs the same steps.
-- Tenants, their templates and the Admin change allowance are not touched.
BEGIN;
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(742918);
SET LOCAL search_path TO knockout_master, pg_catalog;
CREATE TABLE IF NOT EXISTS master_audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NULL REFERENCES companies(id) ON DELETE SET NULL,company_name VARCHAR(160) NOT NULL DEFAULT '',action VARCHAR(40) NOT NULL,detail VARCHAR(300) NOT NULL DEFAULT '',actor_id BIGINT NULL,actor_name VARCHAR(120) NOT NULL DEFAULT '',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS master_user_preferences (master_user_id BIGINT PRIMARY KEY REFERENCES master_users(id) ON DELETE CASCADE,template_id BIGINT NULL REFERENCES ui_templates(id) ON DELETE SET NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS master_audit_company ON master_audit_events (company_id,id);
CREATE INDEX IF NOT EXISTS master_audit_time ON master_audit_events (created_at);
COMMIT;
